 const descriptor=el=>{if(!el)return null;const attrs=['data-variant','data-transport','data-confirm-plan','data-tool','data-tool-item','data-row-index','data-home-step','data-day-step-toggle'];for(const name of attrs)if(el.hasAttribute(name))return '['+name+'="'+CSS.escape(el.getAttribute(name))+'"]';return el.id?'#'+CSS.escape(el.id):null;};
 const visible=el=>{if(!el?.isConnected||!el.getClientRects().length)return false;const r=el.getBoundingClientRect();return r.bottom>stickyBottom&&r.top<innerHeight-62;};
