 if(control&&root?.contains(control)&&control.matches('button,input,select,a'))remember(control);
 if(!candidates.length){const nodes=[...root.querySelectorAll('.timeline-row,.tb-card,.tb-other,.home-day-summary,.utility-header,summary')];const first=nodes.find(el=>visible(el)&&el.getBoundingClientRect().top>=stickyBottom+4)||nodes.find(visible);remember(first);}
 const focus=root?.contains(document.activeElement)?document.activeElement:null,focusSelector=descriptor(focus),originalY=scrollY;
 const transaction={overflow:document.documentElement.style.overflowAnchor,frame:0,observer:null,route:routeState.hash};readingLayout=transaction;document.documentElement.style.overflowAnchor='none';
 readingMutationDepth++;try{update();}catch(error){releaseReadingPosition();throw error;}finally{readingMutationDepth--;}
 const resolve=x=>x.el.isConnected&&x.el.getClientRects().length?x.el:x.selector?root.querySelector(x.selector):null;
 const restore=()=>{if(readingLayout!==transaction||transaction.route!==routeState.hash)return;const saved=candidates.find(x=>resolve(x)?.getClientRects().length),target=saved&&resolve(saved);if(target){const delta=target.getBoundingClientRect().top-saved.top;if(Math.abs(delta)>.5)window.scrollBy({top:delta,behavior:'instant'});}else if(scrollY!==originalY)window.scrollTo({top:originalY,behavior:'instant'});};
