function refreshJourneyZone(now){if(state.view!=='day')return;const el=$('.day-clock[data-compact-clock] > span'),d=DATA.days[state.day-1],t=tripToday(now,DATA.days,tripCalendarChanges),zone=t.inTrip&&t.day===d.id?t.zone:d.tz;if(el&&el.querySelector('time')?.dataset.clockZone!==zone)el.innerHTML=esc(zoneLabel(zone).replace('北京时间','北京').replace('时间',''))+' <time data-clock-zone="'+zone+'"></time>';}
function refreshWeatherLocation(d,now){const el=$('.travel-weather');if(!el||el.dataset.userPlace==='true')return;const chosen=WEATHER_SERVICE.selected(d,selectedPlan(d),now),select=el.querySelector('[data-weather-place]');if(chosen&&select&&select.value==='auto'&&el.dataset.weatherKey!==chosen.key){el.outerHTML=WEATHER_SERVICE.renderShell(d,selectedPlan(d),now);const next=$('.travel-weather');WEATHER_SERVICE.mount(next,d,selectedPlan(d),now);}}
function refreshJourneyWeather(d){const el=$('.travel-weather');if(!el)return;const oldKey=el.dataset.weatherKey,wasManual=el.dataset.userPlace==='true',selected=el.querySelector('[data-weather-place]')?.value,previous=el.querySelector('[data-weather-result]')?.innerHTML;el.outerHTML=WEATHER_SERVICE.renderShell(d,selectedPlan(d));const replacement=$('.travel-weather'),select=replacement?.querySelector('[data-weather-place]');if(select&&[...select.options].some(o=>o.value===selected)){select.value=selected;const place=selected==='auto'?WEATHER_SERVICE.selected(d,selectedPlan(d)):WEATHER_SERVICE.choices(d,selectedPlan(d)).find(p=>p.key===selected);if(place){replacement.querySelector('[data-weather-official]').href=place.official;if(place.key===oldKey)replacement.querySelector('[data-weather-result]').innerHTML=previous;}}if(replacement)replacement.dataset.userPlace=String(wasManual&&select?.value!=='auto');if(replacement)WEATHER_SERVICE.mount(replacement,d,selectedPlan(d));}
function openJourneyParking(key){if(typeof PRACTICAL_TRAVEL!=='undefined'&&PRACTICAL_TRAVEL.parking(key)){openDrawer((DATA.places[key]?.name||'地点')+' · 停车与缴费',PRACTICAL_TRAVEL.parkingBody(key));return;}const p=TRAVEL_SUPPORT.placeParking(key);if(!p)return;openDrawer((DATA.places[key]?.name||'地点')+' · 停车与缴费',`<p>${inline(p.text)}</p>${p.action?'<p>'+esc(p.action)+'</p>':''}<div class="inline-actions">${p.links.map(x=>ext(x.url,x.label,'primary-link')).join('')}</div><p class="info-caption">以现场收费区域、车牌及付款结果为准。</p>`);}
function refreshTemporalTools(){return preserveReadingPosition(refreshTemporalToolsContent);}
function refreshTemporalToolsContent(){const el=$('#toolContent');if(!el||el.contains(document.activeElement))return;const active=[...el.querySelectorAll('details[open]')].map(x=>x.querySelector('summary')?.textContent);const before=el.getBoundingClientRect().height,html=toolBody(toolCategory);if(el.dataset.temporalKey===html)return;el.dataset.temporalKey=html;el.innerHTML=html;for(const d of el.querySelectorAll('details'))if(active.includes(d.querySelector('summary')?.textContent))d.open=true;mountJourney();}
function updatePastSteps(pos){return preserveReadingPosition(()=>updatePastStepsContent(pos));}
function updatePastStepsContent(pos){if(!pos.live)return;const timeline=$('#planTimeline .timeline');if(!timeline)return;let group=null;for(const row of [...timeline.querySelectorAll(':scope > .timeline-row')]){const i=+row.dataset.rowIndex;const box=row.getBoundingClientRect();if(!pos.past[i]||(box.bottom>0&&box.top<innerHeight)||row.contains(document.activeElement)){group=null;continue;}if(!group){group=document.createElement('details');group.className='journey-disclosure past-steps';group.innerHTML='<summary>此前安排 <span>展开查看</span></summary><div class="journey-detail-body"></div>';timeline.insertBefore(group,row);}group.querySelector('.journey-detail-body').append(row);}mountJourney();}
function mountJourney(){const el=$('.travel-weather');if(el&&state.view==='day'){const d=DATA.days[state.day-1];WEATHER_SERVICE.mount(el,d,selectedPlan(d));}document.querySelectorAll('.journey-disclosure').forEach(el=>{if(el.dataset.motionMounted)return;el.dataset.motionMounted='true';const summary=el.querySelector(':scope > summary');summary?.addEventListener('click',e=>{if(reduced())return;e.preventDefault();const closing=el.dataset.motionTarget==='open'||(el.open&&el.dataset.motionTarget!=='closed');el.dataset.motionTarget=closing?'closed':'open';const start=el.getBoundingClientRect().height;el.getAnimations().forEach(a=>a.cancel());el.style.height='auto';el.open=true;const target=closing?summary.getBoundingClientRect().height:el.getBoundingClientRect().height;el.style.overflow='hidden';const anim=el.animate([{height:start+'px'},{height:target+'px'}],{duration:210,easing:'cubic-bezier(.2,.75,.2,1)'});anim.onfinish=()=>{el.open=!closing;el.style.overflow='';el.style.height='';delete el.dataset.motionTarget;};});});}
history.scrollRestoration='manual';parseRoute();render();history.replaceState({route:currentHash(),context:contextSnapshot()},'','#'+currentHash());
let offlineRegistration=null;
function offlineBody(){let verified='尚未在此浏览器核验。';try{const saved=JSON.parse(localStorage.getItem('nordic-offline-verified')||'null');if(saved?.at)verified='上次保存：'+new Date(saved.at).toLocaleString('zh-CN');}catch{}return `<p>离线关键资料包含每日安排、酒店、报到地点、航班与应急电话。外部导航、天气道路查询需要联网，照片仅浏览后缓存。</p><p id="offlineStatus" role="status">${verified}</p><button class="primary-link" data-cache-prepare>准备并核验离线资料</button><div class="offline-links"><a href="essentials.html">精简资料页 · 可打印 / 保存 ↗</a><details><summary>早期完整资料存档</summary><p>以下存档保留旧安排，包括10月30日旧人数。请以当前路书和上方精简资料页为准。</p><a href="offline.html" download="北境路书_2026_历史存档.html">下载历史存档（约12MB） ↓</a><a href="compat.html">阅读历史存档 ↗</a></details></div><p class="info-caption">微信可能限制下载或清除缓存。请在系统浏览器保存关键资料并断网重开同一网址，注册缓存服务不能代替验证。</p>`;}
async function prepareOffline(){const status=$('#offlineStatus');if(!navigator.serviceWorker){status.textContent='此浏览器不支持缓存，请保存精简资料页。';return;}status.textContent='正在准备并核验，请保持网络连接…';try{const latestResponse=await fetch(new URL('offline-manifest.json',document.baseURI),{cache:'no-store'});if(!latestResponse.ok)throw Error('无法获取最新离线清单');const latestManifest=await latestResponse.json();offlineRegistration=await navigator.serviceWorker.register(new URL('sw.js',document.baseURI));await offlineRegistration.update();const installing=offlineRegistration.installing;if(installing)await new Promise((resolve,reject)=>{const changed=()=>{if(installing.state==='installed')resolve();else if(installing.state==='redundant')reject(Error('新版离线资源安装失败，请保持联网后重试'));};installing.addEventListener('statechange',changed);changed();});if(offlineRegistration.waiting)throw Error('存在新版本，请点更新并重开后再保存');await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('缓存安装未完成，请联网后重试')),30000);navigator.serviceWorker.ready.then(r=>{clearTimeout(timer);resolve(r)},e=>{clearTimeout(timer);reject(e)});});const worker=offlineRegistration.active;if(!worker)throw Error('缓存服务尚未启动');const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>reject(Error('准备超时，请联网后重试')),90000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve(e.data):reject(Error(e.data.error||'部分资源保存失败'));};worker.postMessage({type:'PREPARE',version:latestManifest.version},[channel.port2]);});if(result.version!==latestManifest.version)throw Error('存在新版本，请更新并重开后再保存');status.textContent=`行程、住宿、航班与应急资料已保存。请断网重开同一网址试读。`;try{localStorage.setItem('nordic-offline-verified',JSON.stringify({at:new Date().toISOString(),version:result.version}));}catch{}}catch(e){status.textContent='未完成离线准备：'+e.message+'。可保存精简资料页。';}}

function reportOfflineBuild(){const worker=navigator.serviceWorker?.controller||offlineRegistration?.active;worker?.postMessage({type:'CLIENT_BUILD',build:ROADBOOK_CLIENT_BUILD});}
function applyOfflineUpdate(){if(offlineRegistration?.waiting)offlineRegistration.waiting.postMessage({type:'ACTIVATE'});else location.reload();}
if(navigator.serviceWorker&&location.protocol!=='file:')navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).then(r=>{offlineRegistration=r;const offer=()=>{if(r.waiting&&navigator.serviceWorker.controller&&!$('.update-banner')){const banner=document.createElement('aside');banner.className='update-banner';banner.innerHTML='路书有新版本 <button data-update>更新并重开</button>';document.body.append(banner);}};offer();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',offer));}).catch(()=>{});
navigator.serviceWorker?.addEventListener('controllerchange',reportOfflineBuild);
navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='REQUEST_CLIENT_BUILD')reportOfflineBuild();});
if(navigator.serviceWorker&&location.protocol!=='file:')navigator.serviceWorker.ready.then(reportOfflineBuild).catch(()=>{});
window.addEventListener('pageshow',reportOfflineBuild);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')reportOfflineBuild();});
